<script setup lang="ts">
import{computed,reactive,ref}from'vue';import{Head,Link,router,usePage}from'@inertiajs/vue3';import{route}from'ziggy-js';interface Catalogo{id:string;nombre:string;estado:string}interface Proveedor extends Catalogo{documento:string}interface Repuesto{id:string;codigo:string;nombre:string;descripcion?:string;unidad:string;stock_actual:string;stock_minimo:string;costo_referencia:string;precio_venta:string;categoria_id:string;proveedor_id?:string}const props=defineProps<{repuesto:Repuesto;categorias:Catalogo[];proveedores:Proveedor[]}>();const errors=computed<Record<string,string>>(()=>usePage().props.errors as Record<string,string>);const procesando=ref(false);const state=reactive({codigo:props.repuesto.codigo,nombre:props.repuesto.nombre,descripcion:props.repuesto.descripcion||'',categoriaId:props.repuesto.categoria_id,proveedorId:props.repuesto.proveedor_id||'',unidad:props.repuesto.unidad,stockMinimo:props.repuesto.stock_minimo,costoReferencia:props.repuesto.costo_referencia,precioVenta:props.repuesto.precio_venta});function guardar(){procesando.value=true;router.put(route('inventario.repuestos.update',props.repuesto.id),state,{onFinish:()=>procesando.value=false})}
</script>
<template><Head :title="`Editar ${repuesto.codigo}`"/><UDashboardPanel><template #header><UDashboardNavbar :title="`Editar ${repuesto.codigo}`"><template #leading><UDashboardSidebarCollapse/></template></UDashboardNavbar></template><template #body><div class="mx-auto max-w-3xl"><UCard><template #header><div><h2 class="font-semibold">Datos del repuesto</h2><p class="text-sm text-muted">El stock actual es de solo lectura y únicamente cambia mediante movimientos.</p></div></template><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="guardar"><UFormField label="Código" required :error="errors.codigo"><UInput v-model="state.codigo" class="w-full"/></UFormField><UFormField label="Nombre" required :error="errors.nombre"><UInput v-model="state.nombre" class="w-full"/></UFormField><UFormField label="Categoría" required :error="errors.categoriaId"><USelect v-model="state.categoriaId" :items="categorias.map(c=>({label:`${c.nombre}${c.estado!=='activo'?' · '+c.estado:''}`,value:c.id}))" class="w-full"/></UFormField><UFormField label="Proveedor"><USelect v-model="state.proveedorId" :items="proveedores.map(p=>({label:`${p.nombre}${p.estado!=='activo'?' · '+p.estado:''}`,value:p.id}))" class="w-full"/></UFormField><UFormField label="Unidad" required :error="errors.unidad"><USelect v-model="state.unidad" :items="['unidad','litro','metro','kilogramo','juego']" class="w-full"/></UFormField><UFormField label="Stock actual"><UInput :model-value="repuesto.stock_actual" disabled class="w-full"/></UFormField><UFormField label="Stock mínimo" required :error="errors.stockMinimo"><UInput v-model="state.stockMinimo" type="number" min="0" step="0.001" class="w-full"/></UFormField><UFormField label="Costo de referencia" required><UInput v-model="state.costoReferencia" type="number" min="0" step="0.01" class="w-full"/></UFormField><UFormField label="Precio de venta" required><UInput v-model="state.precioVenta" type="number" min="0" step="0.01" class="w-full"/></UFormField><UFormField class="sm:col-span-2" label="Descripción"><UTextarea v-model="state.descripcion" class="w-full"/></UFormField><div class="sm:col-span-2 flex justify-end gap-2"><Link :href="route('inventario.repuestos.show',repuesto.id)"><UButton color="neutral" variant="outline" label="Cancelar"/></Link><UButton type="submit" label="Guardar cambios" :loading="procesando"/></div></form></UCard></div></template></UDashboardPanel></template>
